import test from 'node:test';
import assert from 'node:assert/strict';

import { greet } from '../src/greet.js';

test('greets a regular name', () => {
  assert.equal(greet('World'), 'Hello, World!');
});

test('trims surrounding whitespace of name', () => {
  assert.equal(greet('  Alice  '), 'Hello, Alice!');
  assert.equal(greet('\t Bob \n'), 'Hello, Bob!');
});

test('whitespace-only name greets as empty', () => {
  assert.equal(greet(''), 'Hello, !');
  assert.equal(greet('   '), 'Hello, !');
});

test('keeps internal spacing as given', () => {
  assert.equal(greet('Ada Lovelace'), 'Hello, Ada Lovelace!');
});
